std::set<Point2d> intersectionPoints;

// Iterate through all pairs of segments
for (size_t i = 0; i < segments.size(); ++i) {
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& seg1 = segments[i];
        const Segment2d& seg2 = segments[j];

        char code;
        Point2d intersectionPoint;
        checkSegmentIntersection2(seg1, seg2, code, cg3::CG3_EPSILON, intersectionPoint);

        // Add intersection point if segments intersect
        if (code == '1' || code == 'v' || code == 'e') {
            intersectionPoints.insert(intersectionPoint);
        }
        // Handle collinear overlapping segments (code 'e')
        else if (code == 'e') {
            // Check if segments overlap and add all overlapping points
            // This is a simplified approach - for exact implementation,
            // we would need to find the overlapping portion
            intersectionPoints.insert(intersectionPoint);
        }
    }
}

// Convert set to vector for return
return std::vector<Point2d>(intersectionPoints.begin(), intersectionPoints.end());

